// Run after the Expo widget bundle is generated by the iOS build:
// node --test scripts/test-widget-runtime.cjs
// Uses the actual isolated Expo UI runtime, not a mock of its rendering API.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { test } = require('node:test');
const babel = require('@babel/core');

const root = path.resolve(__dirname, '..');
let layout;
const transformed = babel.transformFileSync(path.join(root, 'src/widgets/MomoraMemoryWidget.tsx'), {
  presets: ['babel-preset-expo'],
  caller: { name: 'metro', platform: 'ios' },
  babelrc: false,
  configFile: false,
}).code;
vm.runInNewContext(transformed, {
  exports: {},
  require: (name) => name === 'expo-widgets'
    ? { createWidget: (_name, source) => { layout = source; return {}; } }
    : {},
});
assert.equal(typeof layout, 'string', 'Babel must isolate the widget function');
const runtime = fs.readFileSync(path.join(root, 'node_modules/expo-widgets/bundle/build/ExpoWidgets.bundle'), 'utf8');

function render(props) {
  const context = vm.createContext({ console, props });
  vm.runInContext(runtime, context);
  vm.runInContext(`globalThis.__expoWidgetLayout = ${layout}`, context);
  return JSON.stringify(vm.runInContext('__expoWidgetRender(props, {})', context));
}

const memory = {
  kind: 'memory',
  imageKind: 'photo',
  expiresAt: '2099-01-01T00:00:00.000Z',
  dateLabel: 'September 15',
  excerpt: 'Synthetic private memory',
  deepLink: 'momora://widget?memoryId=synthetic&familyId=family',
};

test('text cards are neutral and image cards render in the real isolated Expo runtime', () => {
  const text = render(memory);
  assert.doesNotMatch(text, /Synthetic private memory/);
  assert.match(text, /VStackView/);
  const image = render({ ...memory, imageUri: 'file:///private/synthetic.jpg' });
  assert.match(image, /ImageView/);
  assert.match(image, /synthetic.jpg/);
});

test('an expired picker snapshot cannot reveal its old text, image or target', () => {
  const output = render({ ...memory, expiresAt: '2020-01-01T00:00:00Z', imageUri: 'file:///private/synthetic.jpg' });
  assert.match(output, /Open Momora for photo memories/);
  assert.doesNotMatch(output, /Synthetic private memory|synthetic.jpg|memoryId|September 15/);
});

test('missing or invalid expiry fails closed even for a memory-shaped snapshot', () => {
  for (const expiresAt of [undefined, 'invalid']) {
    const output = render({ ...memory, expiresAt });
    assert.match(output, /Open Momora for photo memories/);
    assert.doesNotMatch(output, /Synthetic private memory|memoryId/);
  }
});

test('photo layout resizes before fitting the widget instead of using intrinsic image size', () => {
  const tree = JSON.parse(render({ ...memory, imageUri: 'file:///private/synthetic.jpg' }));
  const children = Array.isArray(tree.props.children) ? tree.props.children : [tree.props.children];
  const photo = children.find((child) => child.type === 'ImageView');
  const modifiers = photo.props.modifiers;
  assert.equal(modifiers[0].$type, 'resizable');
  assert.deepEqual(modifiers.find((m) => m.$type === 'aspectRatio'), {
    $type: 'aspectRatio', contentMode: 'fill',
  }, 'preserve the source aspect ratio instead of treating a portrait as square');
  assert.ok(modifiers.some((m) => m.$type === 'containerRelativeFrame' && m.axes === 'both'));
  assert.ok(modifiers.some((m) => m.$type === 'clipped' && m.clipped));
  assert.ok(tree.props.modifiers.some((m) => m.$type === 'containerRelativeFrame' && m.axes === 'both'));
  assert.ok(!tree.props.modifiers.some((m) => m.$type === 'padding'), 'no outer frame around the image');
  assert.equal(children.length, 1, 'photo cards have no visible caption/date overlay');
  assert.equal(children[0].type, 'ImageView');
});

 test('old or video-shaped image snapshots are neutral until a valid photo refresh', () => {
  for (const imageKind of [undefined, 'video', 'text', 'audio']) {
    const output = render({ ...memory, imageKind, imageUri: 'file:///private/synthetic.jpg' });
    assert.match(output, /Open Momora for photo memories/);
    assert.doesNotMatch(output, /synthetic.jpg|memoryId|Synthetic private memory/);
  }
});
